<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue';
import { Heart, MessageCircle, ImagePlus, X, RefreshCw, Telescope, BookOpen } from '@lucide/vue';
import SaturnLogo from './SaturnLogo.vue';
import QuizPage from './QuizPage.vue';
import { communityPosts as posts, communityStatus, connectCommunity, refreshCommunity, communityWrite, uploadPhoto } from '../sharedCommunity.js';
const props=defineProps({initialTab:String,initialPost:String});
const emit=defineEmits(['navigate','ask']);
const tab=ref(props.initialTab==='quiz'?'quiz':'feed'),category=ref('全部'),query=ref(''),sort=ref('最新');
const categories=['全部','观星日记','星空摄影','行星观测','天文问答','学习交流'];
const draft=ref({author:'',title:'',content:'',category:'观星日记',target:'',location:''}),images=ref([]),busy=ref(false),error=ref(''),notice=ref('');
const detail=ref(null),activeId=ref(''),comment=ref('');let stop;
try{draft.value.author=localStorage.getItem('xingyu-nickname')||''}catch{}
const filtered=computed(()=>{let a=posts.value.filter(p=>(category.value==='全部'||p.category===category.value)&&(p.title+' '+p.content+' '+p.target).includes(query.value.trim()));return sort.value==='热门'?[...a].sort((a,b)=>b.likes-a.likes):a});
const hot=computed(()=>[...posts.value].sort((a,b)=>(b.likes+b.comments.length)-(a.likes+a.comments.length)).slice(0,6));
const active=computed(()=>posts.value.find(p=>p.id===activeId.value));
function date(t){return new Date(t).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'})}
function remember(){try{localStorage.setItem('xingyu-nickname',draft.value.author)}catch{}}
async function addImages(e){error.value='';const files=[...e.target.files];if(files.length+images.value.length>6){error.value='一条话题最多上传 6 张照片';return}for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){error.value='照片需为 JPG、PNG 或 WebP，每张小于 8 MB';continue}images.value.push({file,preview:URL.createObjectURL(file)})}e.target.value=''}
function removeImage(i){URL.revokeObjectURL(images.value[i].preview);images.value.splice(i,1)}
async function publish(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const urls=[];for(const image of images.value)urls.push(await uploadPhoto(image.file));await communityWrite('/api/posts',{...draft.value,images:urls});remember();images.value.forEach(i=>URL.revokeObjectURL(i.preview));images.value=[];draft.value.title='';draft.value.content='';draft.value.target='';draft.value.location='';category.value='全部';await refreshCommunity();notice.value='话题已发布，其他访问者现在也能看见。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function openPost(id){activeId.value=id;comment.value='';await nextTick();if(active.value&&!detail.value.open)detail.value.showModal()}
async function like(p){try{await communityWrite('/api/posts/'+p.id+'/like',{});await refreshCommunity()}catch(e){error.value=e.message}}
async function sendComment(){if(!comment.value.trim()||busy.value)return;busy.value=true;try{await communityWrite('/api/posts/'+activeId.value+'/comments',{author:draft.value.author||'观星访客',content:comment.value});remember();comment.value='';await refreshCommunity()}catch(e){error.value=e.message}finally{busy.value=false}}
async function removePost(p){if(!confirm('删除这条话题和评论？'))return;try{await communityWrite('/api/posts/'+p.id+'/delete',{});detail.value.close();await refreshCommunity()}catch(e){error.value=e.message}}
function focusComposer(){tab.value='feed';nextTick(()=>document.getElementById('topic-title')?.focus())}
watch(()=>props.initialTab,v=>tab.value=v==='quiz'?'quiz':'feed');watch(()=>props.initialPost,v=>{if(v)openPost(v)});
watch(posts,()=>{if(props.initialPost&&!activeId.value)openPost(props.initialPost)});
onMounted(()=>{stop=connectCommunity();if(props.initialPost)openPost(props.initialPost)});
onBeforeUnmount(()=>{stop?.();images.value.forEach(i=>URL.revokeObjectURL(i.preview));detail.value?.close()});
</script>
<template><div class="community-v3"><header class="community-banner"><div><span class="light-eyebrow">STARWHISPER COMMUNITY</span><h1>把今晚的星空，分享给彼此。</h1><p>从你看见的月亮，到镜头里的银河。每一次观察，都可以成为新的话题。</p></div><Telescope :size="78" :stroke-width="1"/></header><nav class="community-mode"><button :class="{selected:tab==='feed'}" @click="tab='feed'">观星广场</button><button :class="{selected:tab==='quiz'}" @click="tab='quiz'"><BookOpen :size="18"/>知识问答</button><span>{{communityStatus==='ready'?'共享社区 · 已连接':communityStatus==='loading'?'正在连接共享社区…':'连接中断，可重试'}}</span></nav><QuizPage v-if="tab==='quiz'" @navigate="emit('navigate',$event)"/><div v-else class="community-columns"><div class="community-main"><section class="topic-composer"><div class="composer-heading"><SaturnLogo :size="40"/><h2>今天，你发现了什么？</h2><span>发布观测话题</span></div><form @submit.prevent="publish"><div class="composer-fields"><input v-model="draft.author" maxlength="30" required placeholder="你的观星昵称" aria-label="昵称"/><select v-model="draft.category" aria-label="话题分类"><option v-for="c in categories.slice(1)">{{c}}</option></select></div><input id="topic-title" v-model="draft.title" required minlength="4" maxlength="80" placeholder="给这次发现起一个标题" aria-label="话题标题"/><textarea v-model="draft.content" required minlength="10" maxlength="2000" rows="4" placeholder="记录你看到的行星、星空，分享拍摄过程，或者向大家提一个天文问题…" aria-label="话题正文"></textarea><div class="composer-fields"><input v-model="draft.target" maxlength="40" placeholder="观测对象，如土星 / 猎户座" aria-label="观测对象"/><input v-model="draft.location" maxlength="60" placeholder="观测地点（选填，如杭州）" aria-label="观测地点"/></div><div class="photo-previews"><figure v-for="(img,i) in images" :key="img.preview"><img :src="img.preview" alt="待发布照片"/><button type="button" aria-label="移除照片" @click="removeImage(i)"><X :size="15"/></button></figure></div><div class="composer-bottom"><label class="photo-upload"><ImagePlus :size="20"/>添加照片<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="busy" @change="addImages"/></label><small>{{images.length}} / 6 张 · {{draft.content.length}} / 2000 字</small><button class="button primary" type="submit" :disabled="busy">{{busy?'正在发布…':'发布话题'}}</button></div><p class="publish-note">发布后所有访问者可见。请上传你拍摄或有权分享的照片。</p></form></section><nav class="topic-tabs" aria-label="社区话题分类"><button v-for="c in categories" :class="{selected:category===c}" @click="category=c">{{c}}</button></nav><div class="feed-toolbar"><strong>{{category==='全部'?'星空动态':category}} <small>{{filtered.length}} 条话题</small></strong><div><button :class="{selected:sort==='最新'}" @click="sort='最新'">最新</button><button :class="{selected:sort==='热门'}" @click="sort='热门'">热门</button><button aria-label="刷新社区" @click="refreshCommunity().catch(e=>error=e.message)"><RefreshCw :size="16"/></button></div></div><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-notice" role="status">{{notice}}</p><div v-if="communityStatus==='loading'&&!posts.length" class="feed-empty">正在加载大家的星空故事…</div><div v-else-if="!filtered.length" class="feed-empty"><h2>{{communityStatus==='error'?'社区暂时无法连接':'第一条星空故事，等你来写。'}}</h2><p>发布你观察到的月亮、行星，或分享一张星空照片。</p><button class="button secondary" @click="communityStatus==='error'?refreshCommunity().catch(e=>error=e.message):focusComposer()">{{communityStatus==='error'?'重新连接':'写一条话题'}}</button></div><article v-for="post in filtered" :key="post.id" class="feed-post"><header><SaturnLogo :size="42"/><div><strong>{{post.author}}</strong><small>{{date(post.createdAt)}}<template v-if="post.location"> · {{post.location}}</template></small></div><button class="topic-tag" @click="category=post.category"># {{post.category}}</button></header><h2><button @click="openPost(post.id)">{{post.title}}</button></h2><p class="post-text">{{post.content}}</p><span v-if="post.target" class="observed-target">观测对象 · {{post.target}}</span><div v-if="post.images.length" class="post-photos" :class="{'single-photo':post.images.length===1}"><button v-for="(url,i) in post.images" @click="openPost(post.id)"><img :src="url" :alt="`${post.title}，照片 ${i+1}`" loading="lazy"/></button></div><footer><button @click="openPost(post.id)"><MessageCircle :size="18"/>{{post.comments.length}} 条评论</button><button @click="like(post)"><Heart :size="18"/>{{post.likes}} 次喜欢</button><button @click="emit('ask',post.title)">问问星语</button></footer></article></div><aside class="community-right"><section class="community-invite"><SaturnLogo :size="70"/><h2>仰望，有了同伴。</h2><p>你的照片与讨论会同步给所有访问者。</p><button class="button primary" @click="focusComposer">分享我的发现</button></section><section class="trending-topics"><h2>大家在看</h2><button v-for="(p,i) in hot" @click="openPost(p.id)"><span>{{i+1}}</span><strong>{{p.title}}</strong><small>{{p.likes+p.comments.length}} 次互动</small></button><p v-if="!hot.length">发布后，话题会出现在这里。</p></section><section class="community-right-search"><h2>找一个话题</h2><input v-model="query" placeholder="搜索社区内容" aria-label="搜索社区内容"/></section><section class="community-quiz-entry"><BookOpen :size="32"/><h2>知识问答</h2><p>聊完星空，试试你知道多少宇宙秘密。</p><button class="button secondary" @click="tab='quiz'">开始天文挑战</button></section><section class="community-note"><h3>一起好好聊星空</h3><p>分享观察，说明对象与拍摄过程；推测和已证实的发现请清楚区分。把好奇心留给宇宙，把友善留给彼此。</p></section></aside></div><dialog ref="detail" class="topic-detail-dialog"><template v-if="active"><header><div><span class="topic-tag"># {{active.category}}</span><h2>{{active.title}}</h2></div><button class="icon-button" aria-label="关闭话题" @click="detail.close()"><X :size="22"/></button></header><p class="topic-detail-author">{{active.author}} · {{date(active.createdAt)}} · {{active.location}}</p><p class="post-text">{{active.content}}</p><div class="detail-photos"><img v-for="(url,i) in active.images" :src="url" :alt="`${active.title}，照片 ${i+1}`"/></div><div class="topic-detail-actions"><button class="button secondary" @click="like(active)"><Heart :size="17"/>喜欢 {{active.likes}}</button><button class="button secondary" @click="emit('ask',active.title);detail.close()">问问星语</button><button v-if="active.owned" class="button secondary" @click="removePost(active)">删除我的话题</button></div><h3>{{active.comments.length}} 条评论</h3><article v-for="c in active.comments" class="topic-comment"><strong>{{c.author}}</strong><small>{{date(c.createdAt)}}</small><p>{{c.content}}</p></article><form @submit.prevent="sendComment"><input v-model="draft.author" required maxlength="30" placeholder="你的昵称" aria-label="评论昵称"/><textarea v-model="comment" required maxlength="500" placeholder="说说你的观察与想法" aria-label="评论内容"></textarea><p v-if="error" class="form-error">{{error}}</p><button class="button primary" :disabled="busy||!comment.trim()">{{busy?'正在发送…':'发表评论'}}</button></form></template></dialog></div></template>
